function mostWins(nums: number[]): number {
  const n = nums.length, used = new Array<boolean>(n).fill(false);
  let best = 0;
  const go = (i: number, wins: number): void => {
    if (i === n) { best = Math.max(best, wins); return; }
    for (let j = 0; j < n; j++) {
      if (used[j]) continue;
      used[j] = true;
      go(i + 1, wins + (nums[j] > nums[i] ? 1 : 0));
      used[j] = false;
    }
  };
  go(0, 0);
  return best;
}

