function mostWins(nums: number[]): number {
  const freq = new Map<number, number>();
  let top = 0;
  for (const x of nums) {
    const c = (freq.get(x) ?? 0) + 1;
    freq.set(x, c);
    top = Math.max(top, c);
  }
  return nums.length - top;
}

